-- Generated by scripts/generate-seed-sql.mjs. Run after schema.sql.
-- Only real, referenced history and publications are seeded (status = published).
-- Placeholders (Tanzania / Africa) are published but flagged is_placeholder, so the public timeline
-- invites verified contributions. Editors replace them as sources are confirmed.
set client_min_messages = warning;
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (1628, null, 'Harvey describes the circulation of the blood', 'William Harvey publishes ''Exercitatio Anatomica de Motu Cordis et Sanguinis in Animalibus'', demonstrating that blood circulates continuously, pumped by the heart. Every perfusion circuit rests on this idea.', 'Foundations', 'Global', 'William Harvey', '[{"label":"Harvey W. Exercitatio Anatomica de Motu Cordis et Sanguinis in Animalibus. Frankfurt; 1628."}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (1812, null, 'Le Gallois proposes artificial perfusion', 'French physiologist Julien Jean César Le Gallois suggests that any part of the body could be kept alive if a supply of arterial blood could be injected in place of the heart: the first written concept of artificial perfusion.', 'Foundations', 'Global', 'Julien Jean César Le Gallois', '[{"label":"Le Gallois JJC. Expériences sur le principe de la vie. Paris; 1812."},{"label":"Stoney WS. Evolution of cardiopulmonary bypass. Circulation. 2009;119(21):2844–2853.","url":"https://doi.org/10.1161/CIRCULATIONAHA.108.830174"}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (1885, null, 'Von Frey and Gruber build an early pump-oxygenator', 'In Leipzig, Max von Frey and Max Gruber construct one of the first apparatuses to oxygenate and pump blood through isolated organs: an ancestor of the heart-lung machine.', 'Extracorporeal pioneers', 'Global', 'Max von Frey, Max Gruber', '[{"label":"Stoney WS. Evolution of cardiopulmonary bypass. Circulation. 2009;119(21):2844–2853.","url":"https://doi.org/10.1161/CIRCULATIONAHA.108.830174"}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (1916, null, 'Heparin is discovered', 'Jay McLean, a medical student working with William Howell at Johns Hopkins, identifies an anticoagulant substance later named heparin. Safe anticoagulation made extracorporeal circulation in humans possible.', 'Extracorporeal pioneers', 'Global', 'Jay McLean, William H. Howell', '[{"label":"McLean J. The thromboplastic action of cephalin. Am J Physiol. 1916;41:250–257."},{"label":"Stoney WS. Evolution of cardiopulmonary bypass. Circulation. 2009;119(21):2844–2853.","url":"https://doi.org/10.1161/CIRCULATIONAHA.108.830174"}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (1926, null, 'Brukhonenko''s ''autojektor''', 'In the Soviet Union, Sergei Brukhonenko demonstrates the ''autojektor'', a device for total body perfusion in animals, using donor lungs for oxygenation.', 'Extracorporeal pioneers', 'Global', 'Sergei S. Brukhonenko', '[{"label":"Konstantinov IE, Alexi-Meskishvili VV. Sergei S. Brukhonenko: the development of the first heart-lung machine for total body perfusion. Ann Thorac Surg. 2000;69(3):962–966."}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (1937, null, 'Gibbon reports experimental extracorporeal circulation', 'John H. Gibbon Jr., working with his wife Mary Hopkinson Gibbon, reports maintaining circulation in cats during occlusion of the pulmonary artery, the start of two decades of work towards a clinical heart-lung machine.', 'Extracorporeal pioneers', 'Global', 'John H. Gibbon Jr., Mary Hopkinson Gibbon', '[{"label":"Gibbon JH Jr. Artificial maintenance of circulation during experimental occlusion of pulmonary artery. Arch Surg. 1937;34(6):1105–1131."}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (1953, '6 May 1953', 'First successful open-heart operation with a heart-lung machine', 'Gibbon closes an atrial septal defect in 18-year-old Cecelia Bavolek in Philadelphia, with his machine supporting her circulation and gas exchange for 26 minutes. Cardiopulmonary bypass enters clinical practice.', 'Birth of CPB', 'Global', 'John H. Gibbon Jr.', '[{"label":"Gibbon JH Jr. Application of a mechanical heart and lung apparatus to cardiac surgery. Minn Med. 1954;37(3):171–185."},{"label":"Stoney WS. Evolution of cardiopulmonary bypass. Circulation. 2009;119(21):2844–2853.","url":"https://doi.org/10.1161/CIRCULATIONAHA.108.830174"}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (1954, null, 'Lillehei''s controlled cross-circulation', 'At the University of Minnesota, C. Walton Lillehei and colleagues repair congenital heart defects in children using a parent as the ''oxygenator'' through controlled cross-circulation.', 'Birth of CPB', 'Global', 'C. Walton Lillehei, Morley Cohen, Herbert Warden, Richard Varco', '[{"label":"Lillehei CW, Cohen M, Warden HE, Varco RL. The direct-vision intracardiac correction of congenital anomalies by controlled cross circulation. Surgery. 1955;38(1):11–29."}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (1955, null, 'Mayo-Gibbon pump-oxygenator series', 'John W. Kirklin''s team at the Mayo Clinic reports a series of intracardiac operations using a refined Gibbon-type pump-oxygenator, showing that CPB could be used reproducibly.', 'Birth of CPB', 'Global', 'John W. Kirklin', '[{"label":"Kirklin JW, DuShane JW, Patrick RT, et al. Intracardiac surgery with the aid of a mechanical pump-oxygenator system (Gibbon type): report of eight cases. Proc Staff Meet Mayo Clin. 1955;30(10):201–206."}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (1955, null, 'DeWall-Lillehei bubble oxygenator', 'Richard DeWall develops a simple, disposable bubble oxygenator with Lillehei, making CPB far cheaper and more widely available.', 'Birth of CPB', 'Global', 'Richard A. DeWall, C. Walton Lillehei', '[{"label":"DeWall RA, Warden HE, Read RC, et al. A simple, expendable, artificial oxygenator for open heart surgery. Surg Clin North Am. 1956;36(4):1025–1034."},{"label":"Stoney WS. Evolution of cardiopulmonary bypass. Circulation. 2009;119(21):2844–2853.","url":"https://doi.org/10.1161/CIRCULATIONAHA.108.830174"}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (1955, null, 'Elective cardiac arrest: the idea of cardioplegia', 'Denis Melrose and colleagues in London describe arresting the heart with potassium citrate to provide a still, bloodless field: the starting point of myocardial protection.', 'Birth of CPB', 'Global', 'Denis G. Melrose', '[{"label":"Melrose DG, Dreyer B, Bentall HH, Baker JBE. Elective cardiac arrest. Lancet. 1955;269(6879):21–22."}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (1956, null, 'First membrane oxygenator', 'George Clowes and colleagues describe an artificial lung in which gas exchange happens through a plastic membrane, separating blood from gas. This principle is used by modern oxygenators.', 'Refinement', 'Global', 'George H. A. Clowes Jr.', '[{"label":"Clowes GHA Jr, Hopkins AL, Neville WE. An artificial lung dependent upon diffusion of oxygen and carbon dioxide through plastic membranes. J Thorac Surg. 1956;32(5):630–637."}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (1964, null, 'AmSECT is founded', 'The American Society of Extra-Corporeal Technology is founded, one of the first professional bodies for perfusionists, helping define perfusion as a distinct profession.', 'Refinement', 'Global', null, '[{"label":"American Society of ExtraCorporeal Technology","url":"https://www.amsect.org"}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (1967, '3 Dec 1967', 'First human heart transplant, Cape Town', 'Christiaan Barnard and his team perform the world''s first human-to-human heart transplant at Groote Schuur Hospital, South Africa, with the operation supported by cardiopulmonary bypass. A landmark for cardiac surgery in Africa.', 'Refinement', 'Africa', 'Christiaan Barnard', '[{"label":"Barnard CN. The operation. A human cardiac transplant: an interim report of a successful operation performed at Groote Schuur Hospital, Cape Town. S Afr Med J. 1967;41(48):1271–1274."}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (1972, null, 'First successful prolonged ECMO in an adult', 'J. Donald Hill and colleagues report support of a young trauma patient with respiratory failure for about three days using a membrane oxygenator: the beginning of clinical ECMO.', 'ECMO & life support', 'Global', 'J. Donald Hill', '[{"label":"Hill JD, O''Brien TG, Murray JJ, et al. Prolonged extracorporeal oxygenation for acute post-traumatic respiratory failure (shock-lung syndrome). N Engl J Med. 1972;286(12):629–634.","url":"https://doi.org/10.1056/NEJM197203232861204"}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (1975, null, 'First neonatal ECMO survivor', 'Robert Bartlett''s team successfully supports a newborn with respiratory failure on ECMO, opening the field of neonatal and paediatric extracorporeal life support.', 'ECMO & life support', 'Global', 'Robert H. Bartlett', '[{"label":"Bartlett RH, Gazzaniga AB, Jefferies MR, et al. Extracorporeal membrane oxygenation (ECMO) cardiopulmonary support in infancy. Trans Am Soc Artif Intern Organs. 1976;22:80–93."}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (1975, null, 'American Board of Cardiovascular Perfusion', 'The ABCP is established to certify clinical perfusionists, a key step in professional standards and training.', 'ECMO & life support', 'Global', null, '[{"label":"American Board of Cardiovascular Perfusion","url":"https://www.abcp.org"}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (1989, null, 'ELSO is founded', 'The Extracorporeal Life Support Organization is formed to share data, guidelines and training for ECMO centres worldwide, including its international registry.', 'ECMO & life support', 'Global', null, '[{"label":"Extracorporeal Life Support Organization","url":"https://www.elso.org"}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (2009, null, 'The CESAR trial', 'A UK randomised trial finds that referral to an ECMO-capable centre improves survival without severe disability in adults with severe respiratory failure.', 'Modern era', 'Global', null, '[{"label":"Peek GJ, Mugford M, Tiruvoipati R, et al. Efficacy and economic assessment of conventional ventilatory support versus extracorporeal membrane oxygenation for severe adult respiratory failure (CESAR). Lancet. 2009;374(9698):1351–1363.","url":"https://doi.org/10.1016/S0140-6736(09)61069-2"}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (2016, null, 'Minimal invasive extracorporeal circulation defined', 'An international position paper sets out principles and definitions for minimal invasive extracorporeal circulation (MiECC): closed, low-prime circuits designed to reduce haemodilution and inflammatory response.', 'Modern era', 'Global', null, '[{"label":"Anastasiadis K, Murkin J, Antonitsis P, et al. Use of minimal invasive extracorporeal circulation in cardiac surgery: principles, definitions and potential benefits. A position paper from MiECTiS. Interact Cardiovasc Thorac Surg. 2016;22(5):647–662."}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (2018, null, 'The EOLIA trial', 'An international RCT of early ECMO for very severe ARDS. 60-day mortality was 35% with ECMO vs 46% with conventional care, which did not reach statistical significance; the trial shaped debate and later analyses.', 'Modern era', 'Global', null, '[{"label":"Combes A, Hajage D, Capellier G, et al. Extracorporeal membrane oxygenation for severe acute respiratory distress syndrome. N Engl J Med. 2018;378(21):1965–1975.","url":"https://doi.org/10.1056/NEJMoa1800385"}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (2019, null, 'First joint EACTS/EACTA/EBCP CPB guidelines', 'European surgical, anaesthesia and perfusion bodies publish joint evidence-based guidelines on cardiopulmonary bypass in adult cardiac surgery.', 'Modern era', 'Global', null, '[{"label":"Wahba A, Milojevic M, Boer C, et al. 2019 EACTS/EACTA/EBCP guidelines on cardiopulmonary bypass in adult cardiac surgery. Eur J Cardiothorac Surg. 2020;57(2):210–251.","url":"https://doi.org/10.1093/ejcts/ezz267"}]'::jsonb, true, false, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (1990, 'Date to be verified', 'Perfusion training and practice across Africa', 'PLACEHOLDER. This milestone will document the development of perfusion training programmes and professional practice in Africa. Contributors with verified sources are invited to submit details.', 'Refinement', 'Africa', null, '[]'::jsonb, false, true, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (2000, 'Date to be verified', 'First open-heart surgery with CPB in Tanzania', 'PLACEHOLDER. The date, institution and team of the first cardiopulmonary bypass case performed in Tanzania will be added once confirmed with primary sources (hospital records, publications, or first-hand accounts).', 'Modern era', 'Tanzania', null, '[]'::jsonb, false, true, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (2010, 'Date to be verified', 'Growth of perfusion services in Tanzania', 'PLACEHOLDER. Establishment of dedicated cardiac centres, local perfusion teams and paediatric programmes in Tanzania. Awaiting verified contributions.', 'Modern era', 'Tanzania', null, '[]'::jsonb, false, true, 'published');
insert into public.timeline_milestones (year, year_label, title, description, era, region, people, "references", verified, is_placeholder, status)
values (2020, 'Date to be verified', 'Local perfusion training in Tanzania', 'PLACEHOLDER. Milestones in training Tanzanian perfusionists locally and abroad, including partnerships and the first graduates, to be added from verified sources.', 'Modern era', 'Tanzania', null, '[]'::jsonb, false, true, 'published');
insert into public.publications (title, authors, journal, year, doi, url, summary, key_findings, category, publication_type, content_kind, open_access, status)
values ('2019 EACTS/EACTA/EBCP guidelines on cardiopulmonary bypass in adult cardiac surgery', 'Wahba A, Milojevic M, Boer C, et al.', 'European Journal of Cardio-Thoracic Surgery', 2020, '10.1093/ejcts/ezz267', null, 'Joint guideline from the European Association for Cardio-Thoracic Surgery, the European Association of Cardiothoracic Anaesthesiology and the European Board of Cardiovascular Perfusion covering CPB equipment, circuit management, anticoagulation, blood management and organ protection in adult cardiac surgery.', array['First guideline jointly written by surgeons, anaesthesiologists and perfusionists.','Provides graded recommendations across the whole CPB pathway; consult the full text for each recommendation and its level of evidence.']::text[], 'Cardiopulmonary Bypass', 'Guideline / Consensus Statement', 'original', true, 'published');
insert into public.publications (title, authors, journal, year, doi, url, summary, key_findings, category, publication_type, content_kind, open_access, status)
values ('Efficacy and economic assessment of conventional ventilatory support versus extracorporeal membrane oxygenation for severe adult respiratory failure (CESAR): a multicentre randomised controlled trial', 'Peek GJ, Mugford M, Tiruvoipati R, et al.', 'The Lancet', 2009, '10.1016/S0140-6736(09)61069-2', null, '180 adults with severe but potentially reversible respiratory failure were randomised to conventional management or referral to a single ECMO-capable centre in the UK.', array['Death or severe disability at 6 months: 37% in the ECMO-referral group vs 53% with conventional management.','The trial tested referral to an ECMO centre, not ECMO alone; not all referred patients received ECMO.']::text[], 'ECMO', 'Randomised Controlled Trial', 'original', false, 'published');
insert into public.publications (title, authors, journal, year, doi, url, summary, key_findings, category, publication_type, content_kind, open_access, status)
values ('Extracorporeal membrane oxygenation for severe acute respiratory distress syndrome', 'Combes A, Hajage D, Capellier G, et al.', 'New England Journal of Medicine', 2018, '10.1056/NEJMoa1800385', null, 'The EOLIA trial randomised 249 patients with very severe ARDS to early venovenous ECMO or conventional lung-protective ventilation (with crossover to ECMO allowed as rescue).', array['60-day mortality was 35% with ECMO vs 46% in the control group; the difference was not statistically significant.','28% of control patients crossed over to rescue ECMO, which complicates interpretation.']::text[], 'ECMO', 'Randomised Controlled Trial', 'original', false, 'published');
insert into public.publications (title, authors, journal, year, doi, url, summary, key_findings, category, publication_type, content_kind, open_access, status)
values ('Prolonged extracorporeal oxygenation for acute post-traumatic respiratory failure (shock-lung syndrome)', 'Hill JD, O''Brien TG, Murray JJ, et al.', 'New England Journal of Medicine', 1972, '10.1056/NEJM197203232861204', null, 'Case report describing the first successful prolonged use of a membrane oxygenator to support a young adult with post-traumatic respiratory failure.', array['Historic report widely regarded as the first successful clinical use of adult ECMO.']::text[], 'Extracorporeal Circulation Technology', 'Case Report', 'original', false, 'published');
insert into public.publications (title, authors, journal, year, doi, url, summary, key_findings, category, publication_type, content_kind, open_access, status)
values ('Evolution of cardiopulmonary bypass', 'Stoney WS.', 'Circulation', 2009, '10.1161/CIRCULATIONAHA.108.830174', null, 'Historical review tracing cardiopulmonary bypass from early perfusion experiments to the heart-lung machines and oxygenators of modern cardiac surgery.', array['Narrative history; useful starting point for students and for the site''s history timeline.']::text[], 'Research and Innovation', 'Journal Article', 'original', true, 'published');
insert into public.publications (title, authors, journal, year, doi, url, summary, key_findings, category, publication_type, content_kind, open_access, status)
values ('Educational summary: components of a standard CPB circuit', 'Tanzania Perfusionist Editorial Team', 'Tanzania Perfusionist (educational content)', 2026, null, null, 'A plain-language overview of the main parts of a conventional CPB circuit: venous drainage, venous reservoir, arterial pump (roller or centrifugal), membrane oxygenator with heat exchanger, arterial line filter, cardioplegia delivery, suction and vents, and the monitoring that ties them together.', array['Educational overview for students. It is not a protocol; follow your institution''s procedures.']::text[], 'Cardiopulmonary Bypass', 'Journal Article', 'educational', false, 'published');
insert into public.case_reports (slug, title, age_group, procedure, sections, "references", author, published_at, tags, is_template, status)
values ('case-report-template', 'Case report template: how to structure an educational perfusion case', 'Adult', 'Template', '{"clinical_background":"Age group and relevant history only. Do not include names, dates of birth, hospital numbers, exact dates or any detail that could identify the patient.","surgical_procedure":"Planned and performed procedure, urgency, approach.","perfusion_setup":"Circuit configuration, oxygenator, pump type, prime volume and composition.","cannulation_strategy":"Arterial and venous cannulation sites and sizes, venting.","cpb_parameters":"Target flows, pressures, CPB and cross-clamp times.","temperature_management":"Cooling and rewarming strategy and targets.","cardioplegia_strategy":"Solution, route, dosing interval.","monitoring":"Blood gas management (alpha-stat / pH-stat), electrolytes, lactate, ACT.","challenges":"What was unexpected or difficult.","interventions":"What the team did and why.","outcomes":"Immediate and short-term outcome, in general terms.","lessons_learned":"The teaching point for other perfusionists."}'::jsonb, array['List each source in full, with a DOI or link where available.']::text[], 'Editorial Team', '2026-11-01', array['template']::text[], true, 'published') on conflict (slug) do nothing;
